const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',plus:'<path d="M12 5v14M5 12h14"/>',orders:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 15h4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',package:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5ZM3 8l9 5 9-5M12 13v9M7.5 5.5l9 5"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`}function paintIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}paintIcons();
const initialHall=document.querySelector('#app').innerHTML;
const state={view:'hall',category:'全部任务',search:'',location:'所有地点',sort:'最新发布',verified:false,name:'林同学',orderTab:'published',creditRole:'runner',credit:{runner:80,published:80},events:[],tickets:[],notifications:['欢迎来到搭把手。这里的任务与账号都是演示数据。'],tasks:[
{id:'t1',type:'快递代取',title:'帮取一件小快递，送到明德楼',desc:'普通小件 · 约 1 kg · 送到楼下即可',from:'校园菜鸟驿站',to:'明德楼',fee:4,budget:0,when:'今天 18:30 前',duration:15,name:'陈同学',initial:'陈',time:'2 分钟前',note:'一件日用品快递，请在楼下见面交付。取件码在接单后按需开放。'},
{id:'t2',type:'物品代买',title:'顺路带两本笔记本和一支黑笔',desc:'A5 方格本 · 黑色中性笔 0.5 mm',from:'校园文具店',to:'知行楼',fee:5,budget:25,when:'今天 19:00 前',duration:20,name:'许同学',initial:'许',time:'5 分钟前',note:'预算 25 元。缺货请先联系，不接受未经确认的替代商品。请保留购物小票。'},
{id:'t3',type:'快递代取',title:'南区驿站两件快递，求顺路带回',desc:'2 件小包裹 · 约 2 kg · 无易碎物品',from:'南区快递点',to:'竹园宿舍',fee:5,budget:0,when:'今天 19:30 前',duration:20,name:'周同学',initial:'周',time:'8 分钟前',note:'两件包裹，请核对数量后送到竹园公共交接点。'},
{id:'t4',type:'物品代买',title:'帮带一盒纯牛奶和一包吐司',desc:'常温纯牛奶 250 ml · 原味吐司',from:'校园生活超市',to:'明德楼',fee:4,budget:20,when:'今天 18:45 前',duration:15,name:'宋同学',initial:'宋',time:'12 分钟前',note:'仅需普通包装食品，查看保质期。无货时先联系确认，不需要自行加购。'},
{id:'t5',type:'快递代取',title:'一件书籍包裹，送到知行楼门口',desc:'1 件小包裹 · 约 1.5 kg · 当面交接',from:'校园菜鸟驿站',to:'知行楼',fee:3,budget:0,when:'今天 20:00 前',duration:15,name:'吴同学',initial:'吴',time:'16 分钟前',note:'包裹是书籍，麻烦轻放。如果外包装破损，请先拍照联系。'},
{id:'t6',type:'物品代买',title:'帮带一包抽纸和两节五号电池',desc:'三层抽纸 · 碱性 AA 电池 2 节',from:'校园生活超市',to:'竹园宿舍',fee:4,budget:30,when:'今天 20:30 前',duration:20,name:'叶同学',initial:'叶',time:'20 分钟前',note:'有指定规格，购买前核对；小票随物品一起交付。'}],orders:[{id:'d1001',type:'物品代买',title:'生活用品送到明德楼',desc:'抽纸一包、收纳盒一个',from:'校园生活超市',to:'明德楼',fee:4,budget:30,actual:27,when:'今天 18:30 前',duration:20,name:'江同学',status:'配送中',role:'published',note:'对方已完成采购，商品实际支出 27 元；商品预算差额 3 元将在演示完成时退回。'}]};
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
let afterAccount=null,lastFocus=null,toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3400)}
function notify(message){state.notifications.unshift(message)}
function showModal(title,body,wide=false){if(!modal.open)lastFocus=document.activeElement;modal.classList.toggle('wide',wide);modalContent.innerHTML=`<div class="modal-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭对话框">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();afterAccount=null;if(lastFocus?.isConnected)lastFocus.focus()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
modal.addEventListener('cancel',()=>{afterAccount=null});
function pageHeader(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">CAMPUS TOGETHER</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function updateShell(){document.querySelector('#crumb').textContent=({hall:'任务大厅',orders:'我的订单',credit:'信用中心',guide:'互助指南',seats:'座位互助'})[state.view];document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view));document.querySelector('#order-count').textContent=state.orders.filter(o=>!['已完成','已取消'].includes(o.status)).length;document.querySelector('.profile').innerHTML=`<span class="avatar">${esc(state.name[0])}</span><span>${esc(state.name)}<small>体验账号 · ${state.verified?'已模拟认证':'未认证'}</small></span><span>⌄</span>`}
function navigate(view){if(!['hall','orders','credit','guide','seats'].includes(view))return;state.view=view;location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){updateShell();if(state.view==='hall')renderHall();else if(state.view==='orders')renderOrders();else if(state.view==='credit')renderCredit();else if(state.view==='guide')renderGuide();else renderSeats();paintIcons()}
function filterTasks(){let tasks=state.tasks.filter(t=>(state.category==='全部任务'||t.type===state.category)&&(state.location==='所有地点'||t.to===state.location)&&(t.title+t.desc+t.from+t.to).toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='报酬优先')tasks.sort((a,b)=>b.fee-a.fee);return tasks}
function taskCard(t){return `<article class="task-card"><div class="card-top"><span class="tag ${t.type==='快递代取'?'blue-tag':'orange-tag'}">${icon(t.type==='快递代取'?'package':'bag')}${esc(t.type)}</span><span class="money">¥ ${t.fee}<small>/ 单</small></span></div><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p><div class="route"><span>${esc(t.from)}</span><span>${esc(t.to)}</span></div><div class="task-meta">${icon('clock')}${esc(t.when)}送达 <span>· 约 ${t.duration} 分钟</span></div><div class="card-footer"><div class="card-user"><span class="tiny-avatar">${esc(t.initial||t.name[0])}</span><span>${esc(t.name)}<small>${esc(t.time||'刚刚')} · 已认证</small></span></div><button class="button outline" data-detail="${esc(t.id)}">查看任务</button></div></article>`}
function renderList(){const tasks=filterTasks();document.querySelector('#task-list').innerHTML=tasks.length?tasks.map(taskCard).join(''):`<div class="empty"><span>${icon('search')}</span><h3>暂时没有匹配的任务</h3><p>换个关键词，或试试其他地点。</p><button class="button outline" data-action="reset-filters">清除筛选</button></div>`;document.querySelector('#result-count').textContent=tasks.length;}
function renderHall(){app.innerHTML=initialHall;document.querySelector('.section-heading h2 span').id='result-count';document.querySelector('.filter-panel').innerHTML=`<div class="tabs" role="group" aria-label="任务类别">${['全部任务','快递代取','物品代买'].map(c=>`<button class="${state.category===c?'selected':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div class="filters"><select id="location-filter" aria-label="送达地点">${['所有地点','明德楼','知行楼','竹园宿舍'].map(x=>`<option ${x===state.location?'selected':''}>${x}</option>`).join('')}</select><select id="sort-filter" aria-label="任务排序">${['最新发布','报酬优先'].map(x=>`<option ${x===state.sort?'selected':''}>${x}</option>`).join('')}</select><label class="searchbox">${icon('search')}<input id="task-search" placeholder="搜索任务或地点" aria-label="搜索任务或地点" value="${esc(state.search)}"></label></div>`;const marker=document.querySelector('.services');marker.insertAdjacentHTML('afterend',`<div class="risk-strip"><span>${icon('shield')}</span><div><strong>安全优先 · 场地规则优先</strong><p>规则未核实的地点不开放交易；异常订单先暂停结算并核查。当前全部是演示数据。</p></div><button class="text-button" data-view="guide">查看风险处理规则</button></div>`);if(state.verified){document.querySelector('.welcome-card').innerHTML=`<span class="tag">校园认证 · 体验已开启</span><h2>顺路的你，<br>也能帮上大忙。</h2><p>选择一件力所能及的小事，<br>体验完整的接单流程。</p><button class="button" data-view="credit">查看我的信用</button><div class="trust-line">${icon('shield')}同校认证 · 费用透明 · 双向保障</div>`}const active=state.orders.find(o=>!['已完成','已取消'].includes(o.status));document.querySelector('.rail-card').innerHTML=active?`<div class="rail-heading"><h3>进行中的互助</h3><span class="small-badge">${state.orders.filter(o=>!['已完成','已取消'].includes(o.status)).length}</span></div><span class="tag ${active.disputed?'orange-tag':'blue-tag'}">${active.disputed?'异常处理中':active.status}</span><h4>${esc(active.title)}</h4><p class="subtle">${active.disputed?'订单处理暂停，等待申诉复核':active.role==='published'?'查看同学的履约进度':'你正在帮助一位同学'}</p><div class="progress-track"><i style="width:${progress(active.status)}%"></i></div><div class="progress-labels"><span>已接单</span><span>配送中</span><span>待确认</span></div><button class="text-button" data-view="orders">查看订单进度</button>`:`<h3>暂时没有进行中的互助</h3><p class="subtle space-top">在大厅寻找一件顺路的小事吧。</p>`;renderList();}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t){toast('这项任务已被接走，请查看其他任务');return}showModal('任务详情',`<span class="tag ${t.type==='快递代取'?'blue-tag':'orange-tag'}">${t.type}</span><h3 class="detail-title">${esc(t.title)}</h3><p class="muted">${esc(t.desc)}</p><div class="detail-route"><div class="route"><span>${esc(t.from)}</span><span>${esc(t.to)}</span></div></div><dl class="detail-list"><div><dt>送达时间</dt><dd>${esc(t.when)}</dd></div><div><dt>预计耗时</dt><dd>约 ${t.duration} 分钟</dd></div><div><dt>跑腿净报酬</dt><dd class="blue-text">¥${t.fee.toFixed(2)}</dd></div>${t.budget?`<div><dt>自愿商品垫付上限</dt><dd>¥${t.budget.toFixed(2)}</dd></div>`:''}<div><dt>平台佣金</dt><dd>¥0.00 · 试点方案</dd></div></dl><div class="info-box"><strong>同学的备注</strong><p>${esc(t.note)}</p></div><div class="inline-note">${icon('shield')}取件码和联系方式仅在接单成功后按需可见。</div><p class="demo-note">此任务为演示数据。接单不会产生真实服务或资金交易。</p><button class="button primary full" data-accept="${t.id}">${state.verified?'确认接单 · 体验流程':'先完成模拟校园认证'}</button>`)}
function account(callback){afterAccount=callback||null;showModal('校园认证体验',`<div class="account-symbol">${icon('shield')}</div><h3 class="center">同一个校园，多一份信任</h3><p class="muted center">体验账号只用于预览，不收集真实证件或学号。</p><form id="account-form"><label>体验昵称<input name="nickname" maxlength="12" value="${esc(state.name)}" required></label><label>所在学校<select name="campus"><option>青禾大学 · 主校区（示例）</option></select></label><div class="info-box"><strong>正式产品认证流程</strong><p>手机号登录 → 核验在校身份 → 接单规则学习 → 接单资格审核。当前只模拟通过，不提供真实认证。</p></div><label class="check-label"><input type="checkbox" name="rules" required><span>我理解这是一段模拟流程，已了解<a href="#guide" data-link-view="guide">互助规则</a>。</span></label><button class="button primary full" type="submit">模拟通过校园认证</button></form>`)}
function acceptTask(id){if(!state.verified){account(()=>taskDetail(id));return}if(state.orders.filter(o=>o.role==='runner'&&!['已完成','已取消'].includes(o.status)).length>=1){toast('新接单者同时最多体验 1 个进行中任务');return}const index=state.tasks.findIndex(t=>t.id===id);if(index<0){toast('任务已不可接');return}const t=state.tasks.splice(index,1)[0];state.orders.unshift({...t,status:'已接单',role:'runner',actual:t.budget});notify(`你已接下「${t.title}」，请按时开始服务。`);closeModal();state.orderTab='runner';navigate('orders');toast('接单成功，已进入我的订单（模拟）')}
function minDate(){const d=new Date(Date.now()+30*60000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function publish(){if(!state.verified){account(()=>publish());return}showModal('发布一个校园任务',`<p class="muted">把地点、时间和需求说清楚，同学就能顺路帮上忙。</p><form id="publish-form"><div class="form-grid"><label>任务类型<select name="type" id="publish-type"><option>快递代取</option><option>物品代买</option></select></label><label>最晚送达时间<input type="datetime-local" name="deadline" required min="${minDate()}" value="${minDate()}"></label></div><label>任务标题<input name="title" maxlength="40" placeholder="例如：帮取一个小包裹，送到明德楼" required></label><div class="form-grid"><label>取件 / 购买地点<select name="from"><option>校园菜鸟驿站</option><option>南区快递点</option><option>校园生活超市</option><option>校园文具店</option></select></label><label>送达地点<select name="to"><option>明德楼</option><option>知行楼</option><option>竹园宿舍</option></select></label></div><div id="type-fields"></div><label>补充说明<textarea name="note" rows="2" maxlength="300" placeholder="请写明规格、件数和交接要求，勿填写真实隐私信息。" required></textarea></label><div class="form-grid"><label>跑腿报酬（元）<input id="fee-input" name="fee" type="number" value="3" min="3" max="50" step="0.5" required></label><label>交接方式<select name="delivery"><option>楼下当面交付</option><option>授权指定公共放置点</option></select></label></div><div class="quote" id="quote"></div><label class="check-label"><input name="agreement" type="checkbox" required><span>已确认信息和费用，并了解取消与退款规则。本次为模拟发布。</span></label><button class="button primary full" type="submit">模拟支付并发布</button><p class="demo-note">不扣款、不发送真实任务；体验数据仅在本次页面会话中保留。</p></form>`,true);renderTypeFields();}
function renderTypeFields(){const type=document.querySelector('#publish-type').value;document.querySelector('#type-fields').innerHTML=type==='快递代取'?`<div class="form-grid"><label>包裹件数<input name="count" type="number" value="1" min="1" max="3" required></label><label>总重量（kg）<input name="weight" type="number" value="1" min="0.1" max="5" step="0.1" required></label></div><p class="field-note">最多 3 件 / 5 kg；仅演示普通低值物品，不填写真实取件码。</p>`:`<div class="form-grid"><label>商品预算上限（元）<input name="budget" id="budget-input" type="number" value="30" min="1" max="100" step="0.01" required></label><label>缺货处理<select name="replacement"><option>先联系，确认后替代</option><option>不接受替代</option></select></label></div><p class="field-note">请在说明中填写品牌、规格和数量。商品款多退少补，变更须确认。</p>`;document.querySelector('[name=from]').value=type==='快递代取'?'校园菜鸟驿站':'校园生活超市';updateQuote()}
function updateQuote(){const form=document.querySelector('#publish-form');if(!form)return;const f=Number(form.elements.fee.value)||0,b=Number(form.elements.budget?.value)||0;document.querySelector('#quote').innerHTML=`<span>报酬 ¥${f.toFixed(2)} ${b?`+ 商品预算 ¥${b.toFixed(2)}`:''}<small>平台服务费 ¥0.00</small></span><strong>合计 ¥${(f+b).toFixed(2)}</strong>`}
function progress(status){return ({'待接单':0,'已接单':15,'服务中':35,'配送中':65,'待确认':90,'已完成':100,'已取消':0})[status]||0}
function renderOrders(){let orders=state.orders.filter(o=>o.role===(state.orderTab==='runner'?'runner':'published'));app.innerHTML=pageHeader('每一份托付，都有回音。','跟进互助进度，费用与交付记录清楚可见。',`<button class="button primary" data-action="publish">${icon('plus')}发布任务</button>`)+`<div class="tabs order-tabs"><button class="${state.orderTab==='published'?'selected':''}" data-order-tab="published">我发布的 <span>${state.orders.filter(o=>o.role==='published').length}</span></button><button class="${state.orderTab==='runner'?'selected':''}" data-order-tab="runner">我接下的 <span>${state.orders.filter(o=>o.role==='runner').length}</span></button></div><div class="order-list">${orders.length?orders.map(orderCard).join(''):`<div class="empty panel">${icon('orders')}<h3>这里还没有订单</h3><p>在任务大厅，寻找一次顺路的互助。</p><button class="button primary" data-view="hall">去任务大厅</button></div>`}</div><p class="demo-note">所有状态和金额均为模拟。刷新页面将恢复最初的示例数据。</p>`}
function orderCard(o){const steps=['已接单','服务中','配送中','待确认','已完成'];let actions='';if(o.disputed)actions=`<button class="button outline" data-review="${o.id}">查看处理说明</button>`;else if(o.role==='runner'&&o.status==='已接单')actions=`<button class="button primary" data-advance="${o.id}">开始服务</button>`;else if(o.role==='runner'&&o.status==='服务中')actions=`<button class="button primary" data-advance="${o.id}">${o.type==='物品代买'?'提交采购记录':'确认已取件'}</button>`;else if(o.status==='配送中')actions=`<button class="button primary" data-advance="${o.id}">${o.role==='runner'?'提交送达凭证':'模拟同学送达'}</button>`;else if(o.status==='待确认')actions=`<button class="button primary" data-advance="${o.id}">${o.role==='runner'?'模拟发单者确认':'确认收到物品'}</button>`;else if(o.status==='已完成')actions=`<button class="button outline" data-receipt="${o.id}">费用明细</button>`;else if(o.status==='待接单')actions=`<span class="muted">等待同校同学接单</span>`;const visibleStatus=o.disputed?'异常处理中':o.status;return `<article class="order-card ${o.disputed?'disputed':''}"><div class="order-head"><span class="tag ${o.type==='快递代取'?'blue-tag':'orange-tag'}">${o.type}</span><span class="order-id">演示订单 ${esc(o.id.toUpperCase())}</span><span class="tag ${o.disputed?'orange-tag':o.status==='已完成'?'green-tag':'blue-tag'}">${visibleStatus}</span></div><div class="order-main"><div><h3>${esc(o.title)}</h3><p class="muted">${esc(o.from)} · ${esc(o.to)}</p></div><div class="order-amount">¥${o.fee}<small>跑腿报酬${o.budget?` · 商品预算 ¥${o.budget}`:''}</small></div></div>${o.disputed?`<div class="dispute-banner"><strong>订单已暂停确认和争议款结算</strong><p>${esc(o.issue||'问题待核实')} · 双方可通过平台提交说明，责任核实前不自动扣分。</p></div>`:''}<div class="stepper">${steps.map((s,i)=>`<div class="${steps.indexOf(o.status)>=i?'done':''}"><span>${steps.indexOf(o.status)>i?'✓':i+1}</span><small>${s}</small></div>`).join('')}</div><div class="order-bottom"><span class="subtle">${esc(o.when)}送达 · ${o.role==='runner'?'发单':'接单'}同学：${esc(o.name)}</span><div class="order-actions">${!o.disputed&&!['已完成','已取消','待接单'].includes(o.status)?`<button class="text-button" data-complaint="${o.id}">遇到问题</button>`:''}${!o.disputed&&['已接单','待接单'].includes(o.status)?`<button class="text-button muted" data-cancel="${o.id}">取消任务</button>`:''}${actions}</div></div></article>`}
function advance(id){const o=state.orders.find(x=>x.id===id);if(!o)return;if(o.disputed){showModal('订单暂时暂停',`<div class="info-box"><strong>正在核实订单问题</strong><p>提交问题后，此笔订单的交付确认和争议款结算会暂停。支持人员需分别核对履约记录与付款记录；双方可补充说明。演示原型不会冒充人工裁决，处理结果通过正式平台客服完成。</p></div><button class="button outline full space-top" data-view="guide">查看争议与申诉规则</button>`);return}if(o.status==='已接单'){o.status='服务中';notify('已开始服务，请核对物品信息。');render();toast('已开始服务（模拟）');return}if(o.status==='服务中'){showModal(o.type==='物品代买'?'核对采购记录':'核对取件记录',`<h3>${esc(o.title)}</h3><p class="muted space-top">${o.type==='物品代买'?'核对小票与商品，实际金额不得超过已确认预算。':'核对件数与外包装。演示不提供真实取件码。'}</p><form id="pickup-form" data-id="${id}">${o.type==='物品代买'?`<label>实际商品金额（元）<input type="number" name="actual" required min="0.01" max="${o.budget}" step="0.01" value="${o.budget}"></label>`:''}<label class="check-label"><input type="checkbox" required><span>使用模拟凭证，已核对物品与数量。</span></label><button class="button primary full" type="submit">保存记录，开始配送</button></form>`);return}if(o.status==='配送中'){showModal('提交送达凭证',`<div class="info-box"><strong>${esc(o.to)} · 公共交接点</strong><p>真实服务需要独立交付码或经授权的放置凭证，不能使用快递取件码代替。</p></div><form id="delivery-form" data-id="${id}"><label>演示交付码<input name="code" pattern="246810" maxlength="6" inputmode="numeric" placeholder="输入示例交付码 246810" required></label><p class="field-note">此处公开展示的代码仅供原型体验，不是真实安全校验。</p><button class="button primary full" type="submit">验证并标记送达（模拟）</button></form>`);return}if(o.status==='待确认'){showModal('确认收到物品',`<h3>${esc(o.title)}</h3><p class="muted space-top">确认后将完成此笔演示订单，并增加 1 点对应角色信用。</p><div class="quote"><span>跑腿报酬 <strong>¥${o.fee}</strong></span>${o.budget?`<span>实际商品 ¥${o.actual??o.budget}<small>预算差额退款 ¥${(o.budget-(o.actual??o.budget)).toFixed(2)}</small></span>`:''}</div><button class="button primary full" data-complete="${id}">确认完成（模拟）</button>`);}}
function complete(id){const o=state.orders.find(x=>x.id===id);if(!o||o.status!=='待确认'||o.disputed)return;o.status='已完成';state.credit[o.role]=Math.min(100,state.credit[o.role]+1);state.events.unshift({title:'守约完成互助',desc:o.title,points:'+1',role:o.role});notify(`「${o.title}」已完成，结算已模拟记录。`);closeModal();render();toast('互助已完成，信用 +1（模拟）')}
function renderCredit(){const score=state.credit[state.creditRole];app.innerHTML=pageHeader('认真对待，每一次托付。','守约会被记录，遇到争议也有解释和申诉的机会。')+`<div class="tabs credit-tabs"><button data-credit-role="runner" class="${state.creditRole==='runner'?'selected':''}">接单信用 <span>${state.credit.runner}</span></button><button data-credit-role="published" class="${state.creditRole==='published'?'selected':''}">发单信用 <span>${state.credit.published}</span></button></div><div class="credit-layout"><section class="credit-score"><span>我的${state.creditRole==='runner'?'接单':'发单'}体验信用</span><strong>${score}<small>/ 100</small></strong><div class="score-track"><i style="width:${score}%"></i></div><p>状态良好 · 初始信用 80 分</p><span class="tag">${state.creditRole==='runner'?'新接单者同时最多接 1 单':'守约发单，保障双方体验'}</span><small class="score-note">发单与接单信用独立记录。正式产品采用分角色核实。</small></section><section class="panel credit-intro"><div class="eyebrow">EVERY LITTLE HELP COUNTS</div><h2>靠谱，是慢慢积累的。</h2><p>按约完成任务，每次 +1 信用。<br>每天最多 +3，信用上限 100 分。<br>一条差评不会直接变成处罚。</p><div class="credit-pills"><span>${icon('shield')}证据判责</span><span>${icon('heart')}双向保障</span><span>${icon('check')}支持复核</span></div></section></div><div class="two-panels"><section class="panel"><h2>奖励与行为规则</h2><div class="rule-row"><div><strong>守约完成任务</strong><p>有效交付，无成立的责任投诉</p></div><b class="green-text">+1</b></div><div class="rule-row"><div><strong>无故失约 / 可归责超时</strong><p>核实责任后告知，不自动罚款</p></div><b class="orange-text">−3</b></div><div class="rule-row"><div><strong>擅自弃单 / 虚假信息</strong><p>按证据处理，可提出申诉</p></div><b class="orange-text">−5</b></div><div class="rule-row"><div><strong>未经确认加价 / 伪造进度</strong><p>退款与信用处理分别进行</p></div><b class="orange-text">−10</b></div><button class="text-button" data-view="guide">查看完整权益说明</button></section><section class="panel"><h2>我的信用动态</h2>${state.events.filter(e=>e.role===state.creditRole).length?state.events.filter(e=>e.role===state.creditRole).map(e=>`<div class="rule-row"><div><strong>${esc(e.title)}</strong><p>${esc(e.desc)}</p><small class="subtle">${e.role==='runner'?'接单':'发单'}行为 · 本次体验</small></div><b class="green-text">${e.points}</b></div>`).join(''):`<div class="empty small">${icon('heart')}<h3>从第一份互助开始</h3><p>体验完成一笔订单，查看信用变化。</p></div>`}<button class="button outline" data-action="appeal">信用申诉 / 查看处理</button></section></div>`}
function renderGuide(){app.innerHTML=pageHeader('有规则，才有安心的互助。','发布前看一眼，让双方对时间、费用和交付都有相同预期。')+`<div class="guide-flow">${[['01','认证加入','核验校园身份，了解接单规则'],['02','说清需求','明确地点、时限、规格与费用'],['03','按约履行','关键步骤留证，变更双方确认'],['04','安心完成','核对交付，完成结算与评价']].map(x=>`<div><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><section class="panel risk-register"><div><div class="eyebrow">RISK CONTROL</div><h2>先控风险，再开始互助。</h2><p class="muted">这些边界直接决定哪些任务可以发布，以及出现问题后如何处置。</p></div><div class="risk-grid">${[['校规与占座','场地规则未知时关闭任务。占座只有获得场馆明确许可才开放；任何人都可随时按规则停单。','高风险'],['包裹与商品','核对包裹、采购凭证与送达记录；商品替代和超预算必须先确认。','人工核实'],['资金与退款','费用按商品款、跑腿费分别核对。真实交易须先通过合规支付渠道完成验证。','上线门槛'],['个人信息','大厅不显示取件码和精确住址。完成履约后取消接单者的信息访问。','最少可见'],['投诉与处罚','提交争议后暂停确认与争议款结算，先查证、再通知双方，可申诉复核。','暂停处理'],['人身安全','遵守门禁和天气限制。感觉不安全可停止服务并联系校园应急渠道。','优先处置']].map(r=>`<article><span class="tag ${r[2]==='高风险'||r[2]==='上线门槛'?'orange-tag':'blue-tag'}">${r[2]}</span><h3>${r[0]}</h3><p>${r[1]}</p></article>`).join('')}</div><div class="risk-footer">原型里的认证、支付、退款和客服均为模拟。只有场地规则、支付渠道、隐私保护与客服响应都完成核实后，才能开放真实交易。</div></section><div class="guide-content space-top"><section class="panel"><h2>常见问题</h2>${[['费用由哪些部分组成？','跑腿报酬与商品预算分开显示。当前试点方案平台佣金为 0；商品款按实际凭证多退少补，接单后不能未经同意加价。'],['临时有事，可以取消吗？','未接单或接单者未出发时可免费取消。已经出发、购买或取件后，需要核实已发生的工作、商品与退回成本，不一概全额退款。'],['物品没收到或损坏怎么办？','从订单进入“遇到问题”，提交说明和证据。争议部分暂缓结算，客服核查责任；有异议可以继续申诉。'],['会公开我的手机号和取件码吗？','不会在任务大厅公开。正式产品仅向当前接单者按需展示，履约完成后取消访问。当前演示不收集真实取件码或证件。'],['可以让同学代占座吗？','取决于具体场地规则。规则未知或禁止占座时不开放任务；可通过场馆官方渠道查询和预约，不共享校园账号，不售卖公共座位。'],['哪些任务不能发布？','不支持代签到、代课、学业代做、违规占座、危险或贵重物品运输、药品烟酒代买及其他违规任务。'],['信用低了，还有申诉机会吗？','有。评价与信用分开，处罚需核实事实并告知原因。可以补充证据申请复核，改判后恢复相应分数和权限。']].map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</section><aside><section class="panel"><h3>需要帮助？</h3><p class="muted space-top">任务异常请优先从对应订单提交，方便核对信息。</p><button class="button primary full space-top" data-view="orders">前往我的订单</button><button class="button outline full space-top" data-action="appeal">其他问题与申诉</button></section><div class="prototype-note"><strong>关于这份交互原型</strong><p>青禾大学、同学、订单均为虚构示例。认证、收款、退款与客服流程尚未接入真实服务，请勿提交真实个人资料。</p></div></aside></div>`}
function renderSeats(){app.innerHTML=pageHeader('找到适合学习的位置。','先了解场地规则，再选择合适的互助方式。')+`<div class="seat-notice">${icon('book')}<div><strong>当前演示校园尚未开放代占座任务</strong><p>学校和场馆规则未核实前，不发布收费占座任务，不保证公共座位使用权。</p></div></div><div class="seat-grid">${[['图书馆','官方预约指引','使用学校图书馆官方网站或公众号核对预约规则，由本人完成预约。','查看预约步骤'],['自习教室','空位信息互助','计划支持带时间戳的空位反馈，帮助减少找座时间。当前尚未接入实时数据。','查看功能说明'],['许可场地','短时座位协助','仅在管理方明确许可后开放，按场地限定的方式和时长提供服务。','查看开放条件']].map((x,i)=>`<section class="panel seat-card"><span class="seat-icon">${icon('book')}</span><span class="tag ${i===0?'blue-tag':'orange-tag'}">${i===0?'由本人预约':'待开放'}</span><h2>${x[0]}</h2><h3>${x[1]}</h3><p>${x[2]}</p><button class="button outline" data-seat="${i}">${x[3]}</button></section>`).join('')}</div><section class="panel space-top"><h2>好的互助，也尊重公共空间。</h2><p class="muted space-top">不放物品长期占位、不倒卖预约名额、不共享学生账号、不替别人签到。场馆临时要求终止时，优先遵守管理要求。</p></section>`}
function complaint(id){showModal('反馈任务问题',`<p class="muted">演示工单只保留在当前页面，不会发送给真实客服。</p><form id="complaint-form" data-id="${esc(id)}"><label>问题类型<select name="type"><option>超时 / 未收到物品</option><option>物品损坏或不符</option><option>费用或临时加价</option><option>其他问题</option></select></label><label>具体情况<textarea name="description" required minlength="5" maxlength="500" placeholder="请描述发生了什么（至少 5 字），不要填写敏感信息。" rows="4"></textarea></label><button class="button primary full" type="submit">提交演示工单</button></form>`)}
function appeal(){showModal('申诉与反馈',`<p class="muted">核实事实，听见双方的说明。以下记录仅保存在本次体验中。</p>${state.tickets.length?state.tickets.map(t=>`<div class="ticket"><strong>${esc(t.type)}</strong><span class="tag blue-tag">模拟待受理</span><p>${esc(t.description)}</p></div>`).join(''):''}<form id="appeal-form"><label>反馈类型<select name="type"><option>信用处罚申诉</option><option>平台使用问题</option><option>提出产品建议</option></select></label><label>说明<textarea required minlength="5" maxlength="500" name="description" rows="3" placeholder="请说明原因及可补充的证据（至少 5 字）。"></textarea></label><button class="button primary full" type="submit">保存演示反馈</button></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-link-view]');if(!b)return;if(b.dataset.linkView){e.preventDefault();closeModal();navigate(b.dataset.linkView);return}if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.category){state.category=b.dataset.category;state.view='hall';render();return}if(b.dataset.creditRole){state.creditRole=b.dataset.creditRole;renderCredit();return}if(b.dataset.detail){taskDetail(b.dataset.detail);return}if(b.dataset.accept){acceptTask(b.dataset.accept);return}if(b.dataset.orderTab){state.orderTab=b.dataset.orderTab;renderOrders();return}if(b.dataset.advance){advance(b.dataset.advance);return}if(b.dataset.review){advance(b.dataset.review);return}if(b.dataset.complete){complete(b.dataset.complete);return}if(b.dataset.complaint){complaint(b.dataset.complaint);return}if(b.dataset.cancel){const o=state.orders.find(x=>x.id===b.dataset.cancel);showModal('取消这笔任务？',`<p class="muted">当前尚未开始履约。本次演示可无费用取消；正式交易中的责任仍需依据实际情况处理。</p><div class="modal-actions"><button class="button outline" data-action="close">继续保留</button><button class="button primary" data-confirm-cancel="${o.id}">确认取消（模拟）</button></div>`);return}if(b.dataset.confirmCancel){const o=state.orders.find(x=>x.id===b.dataset.confirmCancel);if(o&&['待接单','已接单'].includes(o.status)){o.status='已取消';notify('任务已取消，相关款项已模拟退回。')}closeModal();render();toast('任务已取消（模拟）');return}if(b.dataset.receipt){const o=state.orders.find(x=>x.id===b.dataset.receipt);showModal('费用明细 · 模拟结算',`<dl class="detail-list"><div><dt>跑腿报酬</dt><dd>¥${o.fee.toFixed(2)}</dd></div><div><dt>实际商品支出</dt><dd>¥${(o.actual??o.budget).toFixed(2)}</dd></div><div><dt>商品差额退回</dt><dd>¥${(o.budget-(o.actual??o.budget)).toFixed(2)}</dd></div><div><dt>平台佣金</dt><dd>¥0.00</dd></div></dl><p class="demo-note">展示产品结算逻辑，不代表真实资金到账。</p>`);return}if(b.dataset.seat!==undefined){const contents=[['本人预约步骤','1. 在学校官方渠道找到图书馆入口。<br>2. 阅读当前场馆预约和签到规则。<br>3. 本人登录并选择时段，按要求到场。<br><br>本页面为虚构校园，未设置未经核实的预约链接。'],['空位信息功能','规划中的空位信息会展示地点、反馈时间和时效提醒，不保证到达时仍有空位。当前没有接入实时数据，不能据此前往占用座位。'],['开放前需要确认','场馆明确允许相应协助形式；核实最长协助时间；定义交接与失败退款规则；规则有效期内才开放任务。默认关闭代占座交易。']][Number(b.dataset.seat)];showModal(contents[0],`<p class="muted">${contents[1]}</p><button class="button outline full space-top" data-action="close">我知道了</button>`);return}switch(b.dataset.action){case 'close':closeModal();break;case 'publish':publish();break;case 'account':account();break;case 'appeal':appeal();break;case 'campus':showModal('当前校园',`<div class="info-box"><strong>青禾大学 · 主校区</strong><p>用于展示界面和流程的虚构校园。首期产品计划从一个真实校区开始，逐个核实站点、门禁与场地规则。</p></div><button class="button primary full space-top" data-action="close">继续体验</button>`);break;case 'notifications':showModal('消息通知',state.notifications.map((n,i)=>`<div class="notification-row"><span>${icon(i?'orders':'bell')}</span><div><p>${esc(n)}</p><small>本次体验 · 演示消息</small></div></div>`).join(''));break;case 'reset-filters':state.category='全部任务';state.location='所有地点';state.search='';render();break;}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){state.search=e.target.value;renderList()}if(['fee-input','budget-input'].includes(e.target.id))updateQuote()});
document.addEventListener('change',e=>{if(e.target.id==='location-filter'){state.location=e.target.value;renderList()}if(e.target.id==='sort-filter'){state.sort=e.target.value;renderList()}if(e.target.id==='publish-type')renderTypeFields()});
document.addEventListener('submit',e=>{const f=e.target;if(!['account-form','publish-form','pickup-form','delivery-form','complaint-form','appeal-form'].includes(f.id))return;e.preventDefault();if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));if(f.id==='account-form'){const name=data.nickname.trim();if(!name){toast('请填写体验昵称');return}state.name=name;state.verified=true;const cb=afterAccount;closeModal();render();toast('模拟认证完成，可以体验发布与接单');if(cb)cb();return}if(f.id==='publish-form'){if(!state.verified){account();return}const fee=Number(data.fee),budget=Number(data.budget||0);if(!data.title.trim()||!data.note.trim()||new Date(data.deadline).getTime()<=Date.now()||fee<3||fee>50||budget>100){toast('请检查标题、说明、时间与金额');return}const o={id:'d'+Date.now().toString().slice(-8),type:data.type,title:data.title.trim(),desc:data.type==='快递代取'?`${data.count} 件包裹 · ${data.weight} kg`:'按约定规格购买',from:data.from,to:data.to,fee,budget,when:data.deadline.replace('T',' ')+' 前',duration:20,name:state.name,status:'待接单',role:'published',note:data.note.trim()};state.orders.unshift(o);notify('任务已模拟发布。当前体验不连接真实接单者。');closeModal();state.orderTab='published';navigate('orders');toast('模拟发布成功，未产生真实扣款');return}if(f.id==='pickup-form'){const o=state.orders.find(x=>x.id===f.dataset.id);if(o?.status!=='服务中')return;o.actual=Number(data.actual||0);o.status='配送中';closeModal();render();toast('记录已保存，开始配送（模拟）');return}if(f.id==='delivery-form'){if(data.code!=='246810'){toast('请输入演示交付码 246810');return}const o=state.orders.find(x=>x.id===f.dataset.id);if(o?.status!=='配送中')return;o.status='待确认';closeModal();render();toast('已送达，等待确认（模拟）');return}if(['complaint-form','appeal-form'].includes(f.id)){if(data.description.trim().length<5){toast('请至少填写 5 个字的具体说明');return}state.tickets.unshift({type:data.type,description:data.description.trim(),orderId:f.dataset.id});if(f.id==='complaint-form'){const o=state.orders.find(x=>x.id===f.dataset.id);if(o){o.disputed=true;o.issue=data.type}}notify('一份演示反馈已保存。原型不连接真实客服。');closeModal();render();toast(f.id==='complaint-form'?'已暂停任务确认，演示工单已保存':'已保存演示工单，不会发给真实客服')}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['hall','orders','credit','guide','seats'].includes(v)&&v!==state.view){state.view=v;render()}});
if(['hall','orders','credit','guide','seats'].includes(location.hash.slice(1)))state.view=location.hash.slice(1);render();
// Use the exact visible navigation and filtering state for optional browser tools.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_campus_demo_tasks',title:'筛选演示校园任务',description:'Filter demo tasks in the visible hall; does not accept an order or create a transaction.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['全部任务','快递代取','物品代买']},keyword:{type:'string',maxLength:100}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!['全部任务','快递代取','物品代买'].includes(input.category)||(input.keyword!==undefined&&(typeof input.keyword!=='string'||input.keyword.length>100)))throw new Error('无效的任务筛选条件');state.category=input.category;state.search=input.keyword||'';state.location='所有地点';navigate('hall');return {demo:true,count:filterTasks().length,category:state.category}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
